/****************************************************************************
 * app/velaguard/vg_eth.c
 *
 * RJ45（eth0）link/IP/网关采样 + icmp_ping。
 * ping 只判定 RJ45 是否异常；NSH ping 不会改走 ESP。API 见 vg_eth.h。
 ****************************************************************************/

#include <nuttx/config.h>

#include <arpa/inet.h>
#include <net/if.h>
#include <netinet/in.h>
#include <string.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <unistd.h>

#include "netutils/icmp_ping.h"
#include "netutils/netlib.h"

#include "vg_eth.h"

#ifndef VG_ETH_IFNAME
#  define VG_ETH_IFNAME "eth0"
#endif

static int g_ping_replies;
static bool g_last_ping_ok;

/**
  * @brief  icmp_ping 完成回调：记录本轮 reply 个数。
  * @note   仅在 ICMP_I_FINISH 时更新 g_ping_replies；中间进度码忽略。
  * @param  result  netutils icmp_ping 结果结构。
  * @retval None
  */
static void ping_cb(FAR const struct ping_result_s *result)
{
  /* Capture final reply count when the ping sequence finishes */

  if (result->code == ICMP_I_FINISH)
    {
      g_ping_replies = result->nreplies;
    }
}

/**
  * @brief  对指定 host 发送 1 次 ICMP echo（尽量绑定 eth0）。
  * @note   本函数只作 RJ45 健康判定，不会把流量改走 ESP。
  *         timeout 与 NSH ping 对齐为 1000ms；count=1。
  *         若启用 CONFIG_NET_BINDTODEVICE，探测绑定 VG_ETH_IFNAME，
  *         避免误走其它 netdev。
  * @param  host  点分 IPv4 或主机名；NULL/空串视为失败。
  * @retval true  收到至少 1 个 echo reply。
  * @retval false 参数非法、超时或无 reply。
  */
bool vg_eth_ping(FAR const char *host)
{
  struct ping_info_s info;

  /* Reject empty target before touching the stack */

  if (host == NULL || host[0] == '\0')
    {
      return false;
    }

  /* Reset reply counter and fill a one-shot ping request */

  g_ping_replies = 0;
  memset(&info, 0, sizeof(info));
  info.hostname = host;
#ifdef CONFIG_NET_BINDTODEVICE
  info.devname  = VG_ETH_IFNAME;
#endif
  info.count    = 1;
  info.datalen  = 32;
  info.delay    = 0;
  info.timeout  = 1000; /* milliseconds, same as NSH ping */
  info.callback = ping_cb;
  info.priv     = &g_ping_replies;

  /* Blocking icmp_ping; result arrives via ping_cb */

  icmp_ping(&info);
  return g_ping_replies > 0;
}

/**
  * @brief  采样 eth0 link / IPv4 / 网关，并按需执行 ping。
  * @note   link 取自 SIOCGIFFLAGS 的 IFF_RUNNING。
  *         网关优先 DHCP drip；若空且配置了 CONFIG_VG_NET_PING_HOST 则兜底。
  *         do_ping=false 时复用 g_last_ping_ok，避免退避空转把失败 streak 打满。
  *         link 或 IP 缺失时强制 ping_ok=false 并刷新缓存。
  * @param  out      输出采样结构；调用方保证非 NULL。
  * @param  do_ping  true=本拍真正发 ICMP；false=只读缓存。
  * @retval None
  */
void vg_eth_sample(struct vg_eth_sample *out, bool do_ping)
{
  struct ifreq ifr;
  struct in_addr addr;
  int sd;

  /* Clear output; early return leaves all-false / empty strings */

  memset(out, 0, sizeof(*out));
  sd = socket(AF_INET, SOCK_DGRAM, 0);
  if (sd < 0)
    {
      return;
    }

  /* Query IFF_RUNNING on eth0 as RJ45 link indicator */

  memset(&ifr, 0, sizeof(ifr));
  strlcpy(ifr.ifr_name, VG_ETH_IFNAME, IFNAMSIZ);
  if (ioctl(sd, SIOCGIFFLAGS, (unsigned long)&ifr) >= 0)
    {
      out->link = (ifr.ifr_flags & IFF_RUNNING) != 0;
    }

  close(sd);

  /* Read assigned IPv4 address (DHCP or static) */

  if (netlib_get_ipv4addr(VG_ETH_IFNAME, &addr) == 0 && addr.s_addr != 0)
    {
      out->has_ip = true;
      inet_ntop(AF_INET, &addr, out->ip, sizeof(out->ip));
    }

  /* Prefer DHCP gateway as ping target */

  if (netlib_get_dripv4addr(VG_ETH_IFNAME, &addr) == 0 && addr.s_addr != 0)
    {
      inet_ntop(AF_INET, &addr, out->gw, sizeof(out->gw));
    }

#ifdef CONFIG_VG_NET_PING_HOST
  /* Kconfig override when DHCP did not publish a gateway */

  if (out->gw[0] == '\0' && CONFIG_VG_NET_PING_HOST[0] != '\0')
    {
      strlcpy(out->gw, CONFIG_VG_NET_PING_HOST, sizeof(out->gw));
    }
#endif

  /* Without link or IP, RJ45 cannot be healthy — skip ping */

  if (!out->link || !out->has_ip)
    {
      out->ping_ok = false;
      g_last_ping_ok = false;
      return;
    }

  if (do_ping)
    {
      const char *target = out->gw[0] ? out->gw : NULL;
#ifdef CONFIG_VG_NET_PING_HOST
      if (target == NULL && CONFIG_VG_NET_PING_HOST[0] != '\0')
        {
          target = CONFIG_VG_NET_PING_HOST;
        }
#endif

      /* Perform real probe and refresh the last-ok cache */

      out->ping_ok = vg_eth_ping(target);
      g_last_ping_ok = out->ping_ok;
    }
  else
    {
      /* Waiting tick: reuse cache so policy backoff is not polluted */

      out->ping_ok = g_last_ping_ok;
    }
}

/****************************************************************************
 * app/velaguard/vg_eth.h
 *
 * RJ45（eth0）采样与 icmp_ping。ping 只作故障判定，不会故障转移到 ESP。
 ****************************************************************************/

#ifndef __VELAGUARD_VG_ETH_H
#define __VELAGUARD_VG_ETH_H

#include <nuttx/compiler.h>
#include <stdbool.h>
#include <arpa/inet.h>

/**
  * @brief  eth0 一拍采样结果。
  * @note   由 vg_eth_sample() 填充，供 vg_net_mgr 写入 vg_net_sample。
  */
struct vg_eth_sample
{
  bool link;                         /**< IFF_RUNNING */
  bool has_ip;                       /**< DHCP/静态 IPv4 非 0 */
  bool ping_ok;                      /**< 本拍或缓存的最近一次 ping */
  char ip[INET_ADDRSTRLEN];
  char gw[INET_ADDRSTRLEN];          /**< DHCP 网关；空则可用 Kconfig 兜底 */
};

/**
  * @brief  对 host 发 1 次 ICMP echo（绑定 eth0，若启用 BINDTODEVICE）。
  * @note   仅判定 RJ45 上游可达性；NSH `ping` 语义不变，也不会改走 ESP。
  * @param  host  点分 IP 或主机名；NULL/空串返回 false。
  * @retval true  收到至少 1 个 reply。
  * @retval false 超时或失败。
  */
bool vg_eth_ping(FAR const char *host);

/**
  * @brief  采样 link / IP / 网关；可选执行 ping。
  * @note   do_ping=false 时 ping_ok 复用上次成功缓存，
  *         避免退避窗口内的空转把失败 streak 打满。
  * @param  out      输出；不可为 NULL。
  * @param  do_ping  true 时在有 link+IP 时 ping 网关（或 VG_NET_PING_HOST）。
  * @retval None
  */
void vg_eth_sample(struct vg_eth_sample *out, bool do_ping);

#endif

/****************************************************************************
 * app/velaguard/vg_esp_bearer.c
 *
 * ESP-01S AT 承载（lesp_*）。上电 join 作热备；与 vgesp 互斥占用 UART。
 * API 见 vg_esp_bearer.h。
 ****************************************************************************/

#include <nuttx/config.h>

#include <arpa/inet.h>
#include <errno.h>
#include <pthread.h>
#include <string.h>
#include <stdio.h>

#ifdef CONFIG_NETUTILS_ESP8266
#include "netutils/esp8266.h"
#endif

#include "vg_esp_bearer.h"

#ifndef CONFIG_VG_WIFI_SSID
#  define CONFIG_VG_WIFI_SSID "xxx"
#endif
#ifndef CONFIG_VG_WIFI_PASSWORD
#  define CONFIG_VG_WIFI_PASSWORD "1472583690"
#endif

static pthread_mutex_t g_esp_lock = PTHREAD_MUTEX_INITIALIZER;
static bool g_esp_inited;
static bool g_esp_busy;
static char g_ssid[33];
static char g_psk[65];

/**
  * @brief  获取 AT UART 互斥锁。
  * @note   lesp_*、sample、soft_reset 与 status 路径共享此锁，
  *         防止 net_mgr 与并发 AT 调用交错。
  * @retval None
  */
void vg_esp_at_lock(void)
{
  /* Serialize all ESP-01S AT traffic on /dev/ttyS1 */

  pthread_mutex_lock(&g_esp_lock);
}

/**
  * @brief  释放 AT UART 互斥锁。
  * @retval None
  */
void vg_esp_at_unlock(void)
{
  pthread_mutex_unlock(&g_esp_lock);
}

/**
  * @brief  若 RAM 凭据为空，填入 Kconfig 默认 SSID/PSK。
  * @note   仅首次（ssid 空）写入；vg_esp_set_wifi / vgnet wifi 覆盖后不再回填。
  * @retval None
  */
void vg_esp_cred_init(void)
{
  /* Lazy-load compile-time defaults into mutable RAM credentials */

  if (g_ssid[0] == '\0')
    {
      strlcpy(g_ssid, CONFIG_VG_WIFI_SSID, sizeof(g_ssid));
      strlcpy(g_psk, CONFIG_VG_WIFI_PASSWORD, sizeof(g_psk));
    }
}

/**
  * @brief  覆盖 RAM 中的 Wi-Fi 凭据。
  * @note   立即生效于后续 vg_esp_join；不主动断联当前关联。
  * @param  ssid  非空 SSID。
  * @param  psk   密码缓冲（可为空串，视 AP 而定）；不可为 NULL。
  * @retval 0         成功。
  * @retval -EINVAL   参数非法。
  */
int vg_esp_set_wifi(FAR const char *ssid, FAR const char *psk)
{
  if (ssid == NULL || psk == NULL || ssid[0] == '\0')
    {
      return -EINVAL;
    }

  /* Replace in-RAM credentials used by the next join attempt */

  strlcpy(g_ssid, ssid, sizeof(g_ssid));
  strlcpy(g_psk, psk, sizeof(g_psk));
  return 0;
}

/**
  * @brief  查询 net_mgr 是否已占用 ESP UART。
  * @note   vgesp 在 busy 时应拒绝，避免与 lesp worker 抢 /dev/ttyS1。
  * @retval true   已 initialize，UART 归 net_mgr。
  * @retval false  空闲（或未开 NETUTILS_ESP8266）。
  */
bool vg_esp_uart_busy(void)
{
  return g_esp_busy;
}

#ifdef CONFIG_NETUTILS_ESP8266
/**
  * @brief  在已持锁前提下执行 lesp_initialize（幂等）。
  * @note   成功后置 g_esp_busy / g_esp_inited；失败清除 busy。
  * @retval 0     成功或已初始化。
  * @retval 负值  lesp_initialize 失败。
  */
static int vg_esp_init_locked(void)
{
  int ret;

  vg_esp_cred_init();
  if (g_esp_inited)
    {
      return 0;
    }

  /* Mark UART owned before AT init so vgesp can refuse race */

  g_esp_busy = true;
  ret = lesp_initialize();
  if (ret < 0)
    {
      g_esp_busy = false;
      printf("vgnet: lesp_initialize failed\n");
      return ret;
    }

  g_esp_inited = true;
  return 0;
}
#endif

/**
  * @brief  初始化 ESP AT 栈（lesp_initialize）。
  * @note   上电热备路径由 net_mgr 调用；未配置 NETUTILS_ESP8266 时返回 -ENOTSUP。
  * @retval 0       成功或已初始化。
  * @retval -ENOTSUP  未启用 ESP8266 netutils。
  * @retval 负值    lesp 失败。
  */
int vg_esp_init(void)
{
#ifdef CONFIG_NETUTILS_ESP8266
  int ret;

  vg_esp_at_lock();
  ret = vg_esp_init_locked();
  vg_esp_at_unlock();
  return ret;
#else
  return -ENOTSUP;
#endif
}

/**
  * @brief  用当前凭据执行 lesp_ap_connect（热备 join）。
  * @note   与 RJ45 是否健康无关：始终尝试保持关联；TCP 仍仅在策略选 wifi 时走 lesp。
  *         超时参数固定 20（lesp API 单位）。
  * @retval 0         关联成功。
  * @retval -EINVAL   SSID 为空。
  * @retval -ENOTSUP  未启用 ESP8266。
  * @retval 负值      init 或 ap_connect 失败。
  */
int vg_esp_join(void)
{
#ifdef CONFIG_NETUTILS_ESP8266
  int ret;

  vg_esp_cred_init();
  if (g_ssid[0] == '\0')
    {
      return -EINVAL;
    }

  vg_esp_at_lock();
  ret = vg_esp_init_locked();
  if (ret < 0)
    {
      vg_esp_at_unlock();
      return ret;
    }

  /* Hot-standby association; TCP egress remains policy-selected */

  g_esp_busy = true;
  ret = lesp_ap_connect(g_ssid, g_psk, 20);
  vg_esp_at_unlock();
  if (ret < 0)
    {
      printf("vgnet: join %s failed\n", g_ssid);
    }
  else
    {
      printf("vgnet: joined %s\n", g_ssid);
    }

  return ret;
#else
  return -ENOTSUP;
#endif
}

/**
  * @brief  ESP 软复位（AT+RST 路径）；未 init 时先 init。
  * @note   由策略 request_esp_reset 触发；复位后调用方应重新 join。
  * @retval 0         成功。
  * @retval -ENOTSUP  未启用 ESP8266。
  * @retval 负值      失败。
  */
int vg_esp_soft_reset(void)
{
#ifdef CONFIG_NETUTILS_ESP8266
  int ret;

  vg_esp_at_lock();
  if (!g_esp_inited)
    {
      ret = vg_esp_init_locked();
      vg_esp_at_unlock();
      return ret;
    }

  /* Soft reset via lesp; hard RST GPIO is optional and not used here */

  ret = lesp_soft_reset();
  vg_esp_at_unlock();
  return ret;
#else
  return -ENOTSUP;
#endif
}

/**
  * @brief  采样 Wi-Fi 关联与 STA IPv4。
  * @note   本树 lesp_ap_is_connected() 无实现；以 CIPSTA 非零 IP 推断 assoc。
  *         未 init 时输出全清零。
  * @param  out  输出；不可为 NULL。
  * @retval None
  */
void vg_esp_sample(struct vg_esp_sample *out)
{
#ifdef CONFIG_NETUTILS_ESP8266
  in_addr_t ip = 0;
  in_addr_t mask = 0;
  in_addr_t gw = 0;

  memset(out, 0, sizeof(*out));
  vg_esp_at_lock();
  if (!g_esp_inited)
    {
      vg_esp_at_unlock();
      return;
    }

  /* Header declares lesp_ap_is_connected(); this NuttX tree does not
   * implement it. Station IP from CIPSTA is the association signal.
   */

  if (lesp_get_net(lesp_eMODE_STATION, &ip, &mask, &gw) == 0 && ip != 0)
    {
      struct in_addr a;
      a.s_addr = ip;
      out->assoc = true;
      out->has_ip = true;
      inet_ntop(AF_INET, &a, out->ip, sizeof(out->ip));
    }

  vg_esp_at_unlock();
#else
  memset(out, 0, sizeof(*out));
#endif
}

/**
  * @brief  返回当前 SSID（内部静态缓冲的只读指针）。
  * @note   必要时先 cred_init；调用方不得 free / 写入。
  * @retval 指向 g_ssid 的指针。
  */
FAR const char *vg_esp_ssid(void)
{
  vg_esp_cred_init();
  return g_ssid;
}

/****************************************************************************
 * app/velaguard/vg_esp_bearer.h
 *
 * ESP-01S（USART2 /dev/ttyS1）热备：上电 join，与 RJ45 是否健康无关。
 * TCP 仅在策略选中 wifi 时才走 lesp_*。
 ****************************************************************************/

#ifndef __VELAGUARD_VG_ESP_BEARER_H
#define __VELAGUARD_VG_ESP_BEARER_H

#include <nuttx/compiler.h>
#include <arpa/inet.h>
#include <stdbool.h>

/**
  * @brief  ESP 关联与 IP 采样结果。
  * @note   本树 lesp_ap_is_connected() 无实现；assoc 由 STA IP 是否非 0 推断。
  */
struct vg_esp_sample
{
  bool assoc;                        /**< 已关联（由非零 STA IP 推断） */
  bool has_ip;                       /**< STA IPv4 可用 */
  char ip[INET_ADDRSTRLEN];
};

/**
  * @brief  若凭据为空，填入 Kconfig 默认 SSID/PSK。
  * @retval None
  */
void vg_esp_cred_init(void);

/**
  * @brief  获取 AT UART 互斥锁（lesp 与 sample/status 共享）。
  * @retval None
  */
void vg_esp_at_lock(void);

/**
  * @brief  释放 AT UART 互斥锁。
  * @retval None
  */
void vg_esp_at_unlock(void);

/**
  * @brief  net_mgr 是否已占用 ESP UART。
  * @note   vgesp 在 busy 时应拒绝，避免与 lesp worker 抢 /dev/ttyS1。
  * @retval true   已 initialize，UART 归 net_mgr。
  * @retval false  空闲（或未开 VG_NET_FAILOVER / ESP8266）。
  */
bool vg_esp_uart_busy(void);

/**
  * @brief  覆盖 RAM 中的 Wi-Fi 凭据。
  * @param  ssid  非空 SSID。
  * @param  psk   密码（可为空串，视 AP 而定）。
  * @retval 0         成功。
  * @retval -EINVAL   参数非法。
  */
int vg_esp_set_wifi(FAR const char *ssid, FAR const char *psk);

/**
  * @brief  lesp_initialize；成功后标记 UART busy。
  * @retval 0     成功或已初始化。
  * @retval 负值  失败。
  */
int vg_esp_init(void);

/**
  * @brief  用当前凭据 lesp_ap_connect（热备 join）。
  * @note   与 RJ45 健康无关；TCP 仍仅在活动出口为 wifi 时使用 lesp。
  * @retval 0     成功。
  * @retval 负值  失败。
  */
int vg_esp_join(void);

/**
  * @brief  ESP 软复位（AT+RST 路径）；未 init 时先 init。
  * @retval 0     成功。
  * @retval 负值  失败。
  */
int vg_esp_soft_reset(void);

/**
  * @brief  采样关联与 STA IP。
  * @param  out  输出；不可为 NULL。
  * @retval None
  */
void vg_esp_sample(struct vg_esp_sample *out);

/**
  * @brief  当前 SSID（只读指针，指向内部静态缓冲）。
  * @retval 指向内部 g_ssid 的指针。
  */
FAR const char *vg_esp_ssid(void);

#endif

/****************************************************************************
 * app/velaguard/vg_net_policy.c
 *
 * 纯策略实现：无 NuttX / 套接字。主机单测直接链本文件。
 * API 说明见 vg_net_policy.h。
 ****************************************************************************/

#include "vg_net_policy.h"

#include <string.h>

/**
  * @brief  将退避毫秒数钳位到 VG_NET_BACKOFF_MAX_MS。
  * @param  ms  原始等待时间。
  * @retval 钳位后的毫秒数。
  */
static uint32_t clamp_backoff(uint32_t ms)
{
  if (ms > VG_NET_BACKOFF_MAX_MS)
    {
      return VG_NET_BACKOFF_MAX_MS;
    }

  return ms;
}

/**
  * @brief  计算指数退避毫秒数：base×2^exp，封顶 VG_NET_BACKOFF_MAX_MS。
  * @note   jitter_pct 预留；当前故意忽略 RNG，避免纯策略层依赖随机源。
  *         主机单测传 jitter_pct=0；运行时可传 20 但此处仍不抖动。
  * @param  exp         退避指数（0 → 1s，1 → 2s，…）。
  * @param  jitter_pct  计划抖动百分比（未实现）。
  * @retval 退避等待毫秒数。
  */
uint32_t vg_net_policy_backoff_ms(unsigned exp, int jitter_pct)
{
  uint32_t ms = VG_NET_BACKOFF_BASE_MS;
  unsigned i;

  /* Double base until exp exhausted or cap reached */

  for (i = 0; i < exp; i++)
    {
      if (ms > VG_NET_BACKOFF_MAX_MS / 2)
        {
          ms = VG_NET_BACKOFF_MAX_MS;
          break;
        }

      ms *= 2;
    }

  ms = clamp_backoff(ms);

  /* Host tests use jitter_pct=0. Runtime may pass 20; skip RNG here. */

  (void)jitter_pct;
  return ms;
}

/**
  * @brief  清零并标记策略已初始化。
  * @param  p  策略对象。
  * @retval None
  */
void vg_net_policy_init(struct vg_net_policy *p)
{
  memset(p, 0, sizeof(*p));
  p->jitter_pct = 0;
  p->initialized = true;
}

/**
  * @brief  原始 RJ45 健康：link ∧ IP ∧ 本拍 ping_ok。
  * @note   AUTO 模式下最终健康仍受失败 streak 阈值约束。
  */
static bool rj45_raw_ok(const struct vg_net_sample *s)
{
  return s->rj45_link && s->rj45_has_ip && s->rj45_ping_ok;
}

/**
  * @brief  原始 Wi-Fi 健康：已关联且有 STA IP。
  */
static bool wifi_raw_ok(const struct vg_net_sample *s)
{
  return s->wifi_assoc && s->wifi_has_ip;
}

/**
  * @brief  按 inject 覆盖原始健康位。
  * @param  inj  AUTO / FORCE_DOWN / FORCE_UP。
  * @param  raw  采样得到的原始健康。
  * @param  out  覆盖后的输出。
  * @retval None
  */
static void apply_inject(vg_inject_t inj, bool raw, bool *out)
{
  if (inj == VG_INJECT_FORCE_DOWN)
    {
      *out = false;
    }
  else if (inj == VG_INJECT_FORCE_UP)
    {
      *out = true;
    }
  else
    {
      *out = raw;
    }
}

/**
  * @brief  记录一次 Wi-Fi join 结果；失败达阈值时请求软复位。
  * @note   成功清零 fail_streak / backoff_exp。
  *         失败累加；达 VG_NET_ESP_RESET_TRIES 置 request_esp_reset 并清零 streak。
  * @param  p   策略对象。
  * @param  ok  true=join 成功；false=失败。
  * @retval None
  */
void vg_net_policy_note_wifi_join(struct vg_net_policy *p, bool ok)
{
  p->request_esp_reset = false;
  if (ok)
    {
      /* Join recovered — clear failure accounting */

      p->wifi_fail_streak = 0;
      p->wifi_backoff_exp = 0;
      return;
    }

  p->wifi_fail_streak++;
  if (p->wifi_fail_streak >= VG_NET_ESP_RESET_TRIES)
    {
      /* Threshold hit: ask mgr to soft-reset ESP, then restart streak */

      p->request_esp_reset = true;
      p->wifi_fail_streak = 0;
    }

  if (p->wifi_backoff_exp < 16)
    {
      p->wifi_backoff_exp++;
    }
}

/**
  * @brief  一拍策略步进：更新健康判定、活动出口、tcp_backend、tcp_reconnect。
  * @note   规则摘要：
  *         - RJ45 健康 = link ∧ DHCP ∧（连续 ping 失败 < VG_NET_PING_FAIL_N）
  *         - RJ45 挂且 Wi-Fi 可用 → egress=wifi、backend=lesp
  *         - 从 wifi 抢回 rj45 需连续健康满 VG_NET_RJ45_HOLD_MS
  *         - 出口变化时 tcp_reconnect=true；调用方负责关旧 TCP 再开新
  *         - 仅在真实 ping 采样失败时调度退避；等待 tick 不得拉长探测周期
  *         - link 沿 down→up 立即探测（next_rj45_probe_ms = now）
  * @param  p       策略对象（输入/输出）。
  * @param  now_ms  单调时钟毫秒。
  * @param  sample  本拍采样；不可为 NULL。
  * @retval None
  */
void vg_net_policy_step(struct vg_net_policy *p,
                        uint64_t now_ms,
                        const struct vg_net_sample *sample)
{
  bool healthy_rj45;
  bool healthy_wifi;
  vg_egress_t desired;
  vg_egress_t prev;
  bool link_rise;

  if (!p->initialized)
    {
      vg_net_policy_init(p);
    }

  prev = p->active_egress;
  link_rise = sample->rj45_link && !p->prev_rj45_link;
  p->prev_rj45_link = sample->rj45_link;

  /* Link rising edge forces an immediate eth0 probe */

  if (link_rise)
    {
      p->next_rj45_probe_ms = now_ms;
    }

  apply_inject(p->inject_rj45, rj45_raw_ok(sample), &healthy_rj45);
  apply_inject(p->inject_wifi, wifi_raw_ok(sample), &healthy_wifi);

  /* AUTO: apply ping-fail hysteresis; FORCE_*: pin health and streak */

  if (p->inject_rj45 == VG_INJECT_AUTO)
    {
      if (sample->rj45_ping_sampled)
        {
          if (!sample->rj45_ping_ok)
            {
              if (p->rj45_ping_fail_streak < 255)
                {
                  p->rj45_ping_fail_streak++;
                }
            }
          else
            {
              p->rj45_ping_fail_streak = 0;
            }
        }

      healthy_rj45 = sample->rj45_link && sample->rj45_has_ip &&
                     (p->rj45_ping_fail_streak < VG_NET_PING_FAIL_N);
    }
  else if (p->inject_rj45 == VG_INJECT_FORCE_UP)
    {
      p->rj45_ping_fail_streak = 0;
      healthy_rj45 = true;
    }
  else
    {
      p->rj45_ping_fail_streak = VG_NET_PING_FAIL_N;
      healthy_rj45 = false;
    }

  if (healthy_rj45)
    {
      /* Keep eth0 probes running during hysteresis and the 10s hold.
       * After VG_NET_STABLE_RESET_MS online, clear RJ45 backoff exp.
       */

      p->next_rj45_probe_ms = now_ms;
      if (p->rj45_healthy_since_ms == 0)
        {
          p->rj45_healthy_since_ms = now_ms;
        }

      if (p->online_since_ms == 0)
        {
          p->online_since_ms = now_ms;
        }
      else if (now_ms - p->online_since_ms >= VG_NET_STABLE_RESET_MS)
        {
          p->rj45_backoff_exp = 0;
        }
    }
  else
    {
      p->rj45_healthy_since_ms = 0;

      /* Only a real probe schedules backoff. Waiting ticks must not
       * stretch next_rj45_probe_ms or recovery never runs (link stays
       * up, gateway returns, no link-rise edge).
       */

      if (p->inject_rj45 == VG_INJECT_AUTO && sample->rj45_ping_sampled &&
          !sample->rj45_ping_ok && !link_rise)
        {
          uint32_t wait = vg_net_policy_backoff_ms(p->rj45_backoff_exp,
                                                   p->jitter_pct);
          if (p->rj45_backoff_exp < 16)
            {
              p->rj45_backoff_exp++;
            }

          p->next_rj45_probe_ms = now_ms + wait;
        }
    }

  /* Prefer RJ45; hold Wi-Fi until RJ45 healthy window elapses */

  if (healthy_rj45)
    {
      if (p->active_egress == VG_EGRESS_WIFI)
        {
          if (now_ms - p->rj45_healthy_since_ms >= VG_NET_RJ45_HOLD_MS)
            {
              desired = VG_EGRESS_RJ45;
            }
          else
            {
              desired = VG_EGRESS_WIFI;
            }
        }
      else
        {
          desired = VG_EGRESS_RJ45;
        }
    }
  else if (healthy_wifi)
    {
      desired = VG_EGRESS_WIFI;
    }
  else
    {
      desired = VG_EGRESS_NONE;
    }

  /* Publish egress / backend / reconnect for the transport layer */

  p->active_egress = desired;
  p->tcp_reconnect = (desired != prev);

  if (desired == VG_EGRESS_RJ45)
    {
      p->tcp_backend = VG_TCP_POSIX;
      p->state = VG_NET_ONLINE_RJ45;
    }
  else if (desired == VG_EGRESS_WIFI)
    {
      p->tcp_backend = VG_TCP_LESP;
      p->state = VG_NET_ONLINE_WIFI;
    }
  else
    {
      p->tcp_backend = VG_TCP_NONE;
      p->state = VG_NET_DOWN;
    }
}

