/****************************************************************************
 * app/velaguard/vg_tcp_transport.c
 *
 * 单活动 TCP：POSIX 或 lesp_*（句柄或上 VG_MQTT_LESP_TAG）。
 * 提供 MQTT-C pal weak hook。API 见 vg_tcp_transport.h。
 ****************************************************************************/

#include <nuttx/config.h>

#include <errno.h>
#include <netdb.h>
#include <netinet/in.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <sys/time.h>
#include <sys/types.h>
#include <unistd.h>

#ifdef CONFIG_NETUTILS_ESP8266
#include "netutils/esp8266.h"
#endif

#include <mqtt.h>
#include "vg_esp_bearer.h"
#include "vg_tcp_transport.h"

/**
  * @brief  为已连接套接字设置收/发超时（约 2s）。
  * @note   lesp 路径只设 SO_RCVTIMEO 且须持 AT 锁；POSIX 同时设 RCV/SND。
  * @param  fd    原始套接字（无 TAG）。
  * @param  lesp  true=走 lesp_setsockopt。
  * @retval None
  */
static void set_timeo(int fd, bool lesp)
{
  struct timeval tv;
  tv.tv_sec  = 2;
  tv.tv_usec = 0;
#ifdef CONFIG_NETUTILS_ESP8266
  if (lesp)
    {
      vg_esp_at_lock();
      lesp_setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
      vg_esp_at_unlock();
      return;
    }
#endif

  /* POSIX path: apply both receive and send timeouts */

  setsockopt(fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));
  setsockopt(fd, SOL_SOCKET, SO_SNDTIMEO, &tv, sizeof(tv));
}

/**
  * @brief  经内核 TCP（eth0）连接到 host:port。
  * @note   遍历 getaddrinfo 结果直至 connect 成功；成功后设超时。
  * @param  host  Broker 主机名或 IP。
  * @param  port  端口十进制字符串。
  * @retval >=0  POSIX fd。
  * @retval -1   解析或连接失败。
  */
static int posix_connect(const char *host, const char *port)
{
  struct addrinfo hints;
  struct addrinfo *res;
  struct addrinfo *it;
  int fd = -1;
  int ret;

  memset(&hints, 0, sizeof(hints));
  hints.ai_family   = AF_INET;
  hints.ai_socktype = SOCK_STREAM;
  ret = getaddrinfo(host, port, &hints, &res);
  if (ret != 0)
    {
      return -1;
    }

  /* Try each resolved address until one connects */

  for (it = res; it != NULL; it = it->ai_next)
    {
      fd = socket(it->ai_family, it->ai_socktype, it->ai_protocol);
      if (fd < 0)
        {
          continue;
        }

      if (connect(fd, it->ai_addr, it->ai_addrlen) == 0)
        {
          break;
        }

      close(fd);
      fd = -1;
    }

  freeaddrinfo(res);
  if (fd >= 0)
    {
      set_timeo(fd, false);
    }

  return fd;
}

#ifdef CONFIG_NETUTILS_ESP8266
/**
  * @brief  经 ESP AT（lesp_*）连接到 host:port。
  * @note   返回值或上 VG_MQTT_LESP_TAG，供 MQTT-C pal hook 识别。
  *         DNS 与 connect 全程持 AT 锁。
  * @param  host  Broker 主机名或 IP。
  * @param  port  端口十进制字符串。
  * @retval >=0  带 TAG 的 lesp 句柄。
  * @retval -1   DNS / socket / connect 失败。
  */
static int lesp_connect_host(const char *host, const char *port)
{
  struct sockaddr_in addr;
  struct hostent *he;
  int fd;
  int p;

  p = atoi(port);
  vg_esp_at_lock();
  he = lesp_gethostbyname(host);
  if (he == NULL || he->h_addr_list == NULL || he->h_addr_list[0] == NULL)
    {
      vg_esp_at_unlock();
      return -1;
    }

  fd = lesp_socket(PF_INET, SOCK_STREAM, IPPROTO_TCP);
  if (fd < 0)
    {
      vg_esp_at_unlock();
      return -1;
    }

  memset(&addr, 0, sizeof(addr));
  addr.sin_family = AF_INET;
  addr.sin_port   = htons((uint16_t)p);
  memcpy(&addr.sin_addr, he->h_addr_list[0], sizeof(addr.sin_addr));
  if (lesp_connect(fd, (FAR struct sockaddr *)&addr, sizeof(addr)) < 0)
    {
      lesp_closesocket(fd);
      vg_esp_at_unlock();
      return -1;
    }

  vg_esp_at_unlock();
  set_timeo(fd, true);

  /* Tag so mqtt_pal weak hooks divert send/recv to lesp_* */

  return fd | VG_MQTT_LESP_TAG;
}
#endif

/**
  * @brief  按 backend 建立到 host:port 的 TCP 连接。
  * @note   同时只应有一条活动连接；切换出口时须先 vg_tcp_close。
  *         VG_TCP_NONE 或未知 backend 返回 -1。
  * @param  backend  VG_TCP_POSIX 或 VG_TCP_LESP。
  * @param  host     Broker 主机名或 IP。
  * @param  port     端口十进制字符串。
  * @retval >=0  句柄；lesp 路径会或上 VG_MQTT_LESP_TAG。
  * @retval -1   参数非法或建连失败。
  */
int vg_tcp_open(vg_tcp_backend_t backend, const char *host, const char *port)
{
  if (host == NULL || port == NULL)
    {
      return -1;
    }

  if (backend == VG_TCP_POSIX)
    {
      return posix_connect(host, port);
    }

#ifdef CONFIG_NETUTILS_ESP8266
  if (backend == VG_TCP_LESP)
    {
      return lesp_connect_host(host, port);
    }
#endif

  return -1;
}

/**
  * @brief  关闭连接并把 *fd 置为 -1。
  * @note   按 TAG 选择 close 或 lesp_closesocket；lesp 路径持 AT 锁。
  * @param  fd  指向句柄的指针；NULL 或 *fd<0 时无操作。
  * @retval None
  */
void vg_tcp_close(int *fd)
{
  int raw;

  if (fd == NULL || *fd < 0)
    {
      return;
    }

  raw = *fd;
#ifdef CONFIG_NETUTILS_ESP8266
  if (raw & VG_MQTT_LESP_TAG)
    {
      vg_esp_at_lock();
      lesp_closesocket(raw & ~VG_MQTT_LESP_TAG);
      vg_esp_at_unlock();
      *fd = -1;
      return;
    }
#endif

  close(raw);
  *fd = -1;
}

/**
  * @brief  MQTT-C pal weak hook：带 LESP TAG 时走 lesp_send。
  * @note   返回 -1 表示本 hook 不处理，调用方继续默认 POSIX send。
  *         返回 0 表示已处理（成功写 *out=字节数，失败写 MQTT_ERROR_SOCKET_ERROR）。
  * @param  fd     mqtt_pal_socket_handle（可能带 TAG）。
  * @param  buf    发送缓冲。
  * @param  len    字节数。
  * @param  flags  传给 lesp_send。
  * @param  out    输出已发送字节或错误码。
  * @retval 0   本 hook 已处理。
  * @retval -1  非 lesp fd（或 out==NULL）。
  */
int vg_mqtt_pal_try_sendall(mqtt_pal_socket_handle fd, const void *buf,
                            size_t len, int flags, ssize_t *out)
{
#ifdef CONFIG_NETUTILS_ESP8266
  const uint8_t *p = (const uint8_t *)buf;
  size_t sent = 0;

  if (out == NULL || (fd & VG_MQTT_LESP_TAG) == 0)
    {
      return -1;
    }

  /* Drain the full buffer under the AT lock */

  vg_esp_at_lock();
  while (sent < len)
    {
      ssize_t n = lesp_send(fd & ~VG_MQTT_LESP_TAG, p + sent, len - sent,
                            flags);
      if (n < 1)
        {
          vg_esp_at_unlock();
          *out = MQTT_ERROR_SOCKET_ERROR;
          return 0;
        }

      sent += (size_t)n;
    }

  vg_esp_at_unlock();

  *out = (ssize_t)sent;
  return 0;
#else
  (void)fd;
  (void)buf;
  (void)len;
  (void)flags;
  (void)out;
  return -1;
#endif
}

/**
  * @brief  MQTT-C pal weak hook：带 LESP TAG 时走 lesp_recv。
  * @note   语义同 vg_mqtt_pal_try_sendall。
  * @param  fd     mqtt_pal_socket_handle（可能带 TAG）。
  * @param  buf    接收缓冲。
  * @param  bufsz  缓冲大小。
  * @param  flags  传给 lesp_recv。
  * @param  out    输出已收字节或错误码。
  * @retval 0   本 hook 已处理。
  * @retval -1  非 lesp fd。
  */
int vg_mqtt_pal_try_recvall(mqtt_pal_socket_handle fd, void *buf,
                            size_t bufsz, int flags, ssize_t *out)
{
#ifdef CONFIG_NETUTILS_ESP8266
  ssize_t n;

  if (out == NULL || (fd & VG_MQTT_LESP_TAG) == 0)
    {
      return -1;
    }

  vg_esp_at_lock();
  n = lesp_recv(fd & ~VG_MQTT_LESP_TAG, (FAR uint8_t *)buf, bufsz, flags);
  vg_esp_at_unlock();
  if (n < 0)
    {
      *out = MQTT_ERROR_SOCKET_ERROR;
      return 0;
    }

  *out = n;
  return 0;
#else
  (void)fd;
  (void)buf;
  (void)bufsz;
  (void)flags;
  (void)out;
  return -1;
#endif
}

/****************************************************************************
 * app/velaguard/vg_net_mgr.c
 *
 * 故障转移胶水线程：
 *   eth0 ping 采样 → ESP 热备采样 → vg_net_policy_step →
 *   （可选）ESP 复位/重 join → TCP 关旧开新 → mqtt_sync。
 *
 * 同时只维持一条 MQTT TCP。API 见 vg_net_mgr.h。
 ****************************************************************************/

#include <nuttx/config.h>

#include <pthread.h>
#include <stdbool.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#include "vg_esp_bearer.h"
#include "vg_eth.h"
#include "vg_mqtt_session.h"
#include "vg_net_mgr.h"
#include "vg_net_policy.h"
#include "vg_tcp_transport.h"

static pthread_mutex_t g_lock = PTHREAD_MUTEX_INITIALIZER;
static struct vg_net_policy g_policy;
static bool g_started;
static uint64_t g_next_mqtt_ms;
static char g_reason[80];

/**
  * @brief  读取单调时钟毫秒。
  * @retval 自开机起的毫秒数（CLOCK_MONOTONIC）。
  */
static uint64_t now_ms(void)
{
  struct timespec ts;

  clock_gettime(CLOCK_MONOTONIC, &ts);
  return (uint64_t)ts.tv_sec * 1000ull + (uint64_t)(ts.tv_nsec / 1000000ull);
}

/**
  * @brief  将策略 egress 映射为 status JSON 的 network 字段。
  * @note   wifi 出口对外写作 "esp01"（手册用语），策略枚举仍是 wifi。
  * @param  e  活动出口。
  * @retval 静态字符串 rj45|esp01|none。
  */
static const char *net_name(vg_egress_t e)
{
  if (e == VG_EGRESS_RJ45)
    {
      return "rj45";
    }

  if (e == VG_EGRESS_WIFI)
    {
      return "esp01";
    }

  return "none";
}

/**
  * @brief  把 join 结果写入策略，并调度下次 join 时间。
  * @param  ok  true=关联成功（5s 后再采样重试窗口）；false=按退避重试。
  * @retval None
  */
static void note_wifi_result(bool ok)
{
  vg_net_policy_note_wifi_join(&g_policy, ok);
  if (ok)
    {
      g_policy.next_wifi_join_ms = now_ms() + 5000;
    }
  else
    {
      g_policy.next_wifi_join_ms =
        now_ms() + vg_net_policy_backoff_ms(g_policy.wifi_backoff_exp, 0);
    }
}

/**
  * @brief  net_mgr 主循环（detached pthread 入口）。
  * @note   禁止在 LED/NSH 线程里同步跑本循环；join/ping 可能阻塞数秒。
  *         上电先 ESP init+join（热备），再进入 200ms 周期：
  *         sample → policy → reset/join → MQTT 关旧开新 → poll。
  * @param  arg  未使用。
  * @retval NULL（永不返回）。
  */
static void *vg_net_thread(void *arg)
{
  struct vg_eth_sample eth;
  struct vg_esp_sample esp;
  struct vg_net_sample sample;
  uint64_t t;
  bool do_ping;

  (void)arg;
  vg_net_policy_init(&g_policy);
  g_policy.jitter_pct = 20;
  snprintf(g_reason, sizeof(g_reason), "boot");

  /* Boot: initialize ESP AT and attempt hot-standby AP join */

  if (vg_esp_init() == 0)
    {
      if (vg_esp_join() == 0)
        {
          note_wifi_result(true);
        }
      else
        {
          note_wifi_result(false);
        }
    }

  for (; ; )
    {
      t = now_ms();
      do_ping = (t >= g_policy.next_rj45_probe_ms);

      /* Sample bearers; ping eth0 only when policy schedule allows */

      vg_eth_sample(&eth, do_ping);
      vg_esp_sample(&esp);

      memset(&sample, 0, sizeof(sample));
      sample.rj45_link         = eth.link;
      sample.rj45_has_ip       = eth.has_ip;
      sample.rj45_ping_ok      = eth.ping_ok;
      sample.rj45_ping_sampled = do_ping && eth.link && eth.has_ip;
      sample.wifi_assoc        = esp.assoc;
      sample.wifi_has_ip       = esp.has_ip;

      pthread_mutex_lock(&g_lock);
      vg_net_policy_step(&g_policy, t, &sample);

      /* Soft-reset ESP when join failures hit policy threshold */

      if (g_policy.request_esp_reset)
        {
          g_policy.request_esp_reset = false;
          pthread_mutex_unlock(&g_lock);
          printf("vgnet: esp reset\n");
          vg_esp_soft_reset();
          usleep(2000000);
          if (vg_esp_join() == 0)
            {
              pthread_mutex_lock(&g_lock);
              note_wifi_result(true);
            }
          else
            {
              pthread_mutex_lock(&g_lock);
              note_wifi_result(false);
            }
        }

      /* Retry join while disassociated and backoff elapsed */

      if (!esp.assoc && vg_esp_ssid()[0] != '\0' &&
          t >= g_policy.next_wifi_join_ms)
        {
          pthread_mutex_unlock(&g_lock);
          if (vg_esp_join() == 0)
            {
              pthread_mutex_lock(&g_lock);
              note_wifi_result(true);
            }
          else
            {
              pthread_mutex_lock(&g_lock);
              note_wifi_result(false);
            }
        }

      /* Single MQTT TCP: close old then open on the active backend */

      if (g_policy.tcp_reconnect ||
          (g_policy.tcp_backend != VG_TCP_NONE &&
           !vg_mqtt_session_online() && t >= g_next_mqtt_ms))
        {
          vg_tcp_backend_t backend = g_policy.tcp_backend;
          vg_egress_t egress = g_policy.active_egress;

          snprintf(g_reason, sizeof(g_reason), "egress=%s",
                   vg_egress_str(egress));
          pthread_mutex_unlock(&g_lock);
          vg_mqtt_session_close();
          if (backend != VG_TCP_NONE)
            {
              if (vg_mqtt_session_open(backend, net_name(egress)) != 0)
                {
                  g_next_mqtt_ms = now_ms() + 2000;
                }
              else
                {
                  g_next_mqtt_ms = 0;
                }
            }

          pthread_mutex_lock(&g_lock);
        }

      pthread_mutex_unlock(&g_lock);
      vg_mqtt_session_poll();
      usleep(200000);
    }

  return NULL;
}

/**
  * @brief  启动 net_mgr 后台线程（幂等）。
  * @note   attr 只是 create 时的临时配置，create 成功后即可 destroy；
  *         detach 表示无人 join，线程退出时自行回收，并非取消创建。
  *         由 velaguard_app_main 调用；不依赖 NSH。
  * @retval 0   已启动或早已启动。
  * @retval -1  pthread_create 失败。
  */
int vg_net_mgr_start(void)
{
  pthread_t tid;
  pthread_attr_t attr;

  if (g_started)
    {
      return 0;
    }

  /* 8 KiB stack: join/ping/MQTT sync need headroom beyond default */

  pthread_attr_init(&attr);
  pthread_attr_setstacksize(&attr, 8192);
  if (pthread_create(&tid, &attr, vg_net_thread, NULL) != 0)
    {
      pthread_attr_destroy(&attr);
      printf("vgnet: thread create failed\n");
      return -1;
    }

  pthread_attr_destroy(&attr);

  pthread_detach(tid);
  g_started = true;
  printf("vgnet: manager started\n");
  return 0;
}

/**
  * @brief  打印当前策略与承载状态到 out。
  * @note   出口已选定但 MQTT 未 CONNACK 时，对外 state 显示为 connecting。
  *         eth 采样 do_ping=false，避免 status 命令触发额外 ICMP。
  * @param  out  输出流，通常为 stdout。
  * @retval None
  */
void vg_net_mgr_print_status(FILE *out)
{
  struct vg_eth_sample eth;
  struct vg_esp_sample esp;
  vg_net_state_t st;

  vg_eth_sample(&eth, false);
  vg_esp_sample(&esp);

  pthread_mutex_lock(&g_lock);
  st = g_policy.state;
  if ((g_policy.active_egress == VG_EGRESS_RJ45 ||
       g_policy.active_egress == VG_EGRESS_WIFI) &&
      !vg_mqtt_session_online())
    {
      st = VG_NET_CONNECTING;
    }

  fprintf(out,
          "state=%s egress=%s tcp=%s mqtt=%s reason=%s\n"
          "rj45 link=%d ip=%s gw=%s ping_ok=%d fail_streak=%u\n"
          "wifi ssid=%s assoc=%d ip=%s\n",
          vg_net_state_str(st),
          vg_egress_str(g_policy.active_egress),
          vg_tcp_backend_str(g_policy.tcp_backend),
          vg_mqtt_session_online() ? "up" : "down",
          g_reason,
          eth.link, eth.ip[0] ? eth.ip : "-",
          eth.gw[0] ? eth.gw : "-", eth.ping_ok,
          g_policy.rj45_ping_fail_streak,
          vg_esp_ssid(), esp.assoc, esp.ip[0] ? esp.ip : "-");
  pthread_mutex_unlock(&g_lock);
}

/**
  * @brief  注入 bearer 健康覆盖，用于无物理拔线时验收切换。
  * @param  bearer  "rj45" 或 "wifi"。
  * @param  mode    "down" | "up" | "auto"。
  * @retval 0   成功。
  * @retval -1  参数非法。
  */
int vg_net_mgr_inject(const char *bearer, const char *mode)
{
  vg_inject_t inj;

  if (strcmp(mode, "down") == 0)
    {
      inj = VG_INJECT_FORCE_DOWN;
    }
  else if (strcmp(mode, "up") == 0)
    {
      inj = VG_INJECT_FORCE_UP;
    }
  else if (strcmp(mode, "auto") == 0)
    {
      inj = VG_INJECT_AUTO;
    }
  else
    {
      return -1;
    }

  pthread_mutex_lock(&g_lock);
  if (strcmp(bearer, "rj45") == 0)
    {
      g_policy.inject_rj45 = inj;
    }
  else if (strcmp(bearer, "wifi") == 0)
    {
      g_policy.inject_wifi = inj;
    }
  else
    {
      pthread_mutex_unlock(&g_lock);
      return -1;
    }

  pthread_mutex_unlock(&g_lock);
  return 0;
}

/**
  * @brief  覆盖 RAM 中的 Wi-Fi 凭据；下次 join 重试时生效。
  * @param  ssid  AP SSID。
  * @param  psk   AP 密码。
  * @retval 0     成功。
  * @retval 负值  参数非法（见 vg_esp_set_wifi）。
  */
int vg_net_mgr_set_wifi(const char *ssid, const char *psk)
{
  return vg_esp_set_wifi(ssid, psk);
}

/****************************************************************************
 * app/velaguard/vg_mqtt_session.c
 *
 * MQTT-C 常驻会话：CONNACK 才 online；切出口先 close 再 open。
 * status QoS0 retained，network=rj45|esp01|none。API 见 vg_mqtt_session.h。
 ****************************************************************************/

#include <nuttx/config.h>

#include <mqtt.h>
#include <stdbool.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#include "vg_mqtt_session.h"
#include "vg_tcp_transport.h"

#ifndef DEVID
#  define DEVID "vg-test-01"
#endif

#ifndef CONFIG_VG_MQTT_BROKER_HOST
#  define CONFIG_VG_MQTT_BROKER_HOST "107.174.123.74"
#endif
#ifndef CONFIG_VG_MQTT_BROKER_PORT
#  define CONFIG_VG_MQTT_BROKER_PORT 1883
#endif

#define VGMQTT_WILL_MSG "{\"online\":false}"

static int g_fd = -1;
static struct mqtt_client g_client;
static uint8_t g_tx[512];
static uint8_t g_rx[512];
static bool g_online;
static char g_net[8];

/**
  * @brief  将 Kconfig Broker 端口格式化为十进制字符串。
  * @param  buf  输出缓冲。
  * @param  n    缓冲长度。
  * @retval None
  */
static void port_str(char *buf, size_t n)
{
  snprintf(buf, n, "%d", CONFIG_VG_MQTT_BROKER_PORT);
}

/**
  * @brief  关闭当前 MQTT TCP，清除 online 标志。
  * @note   切换出口时必须先调用本函数，禁止双连接并存。
  * @retval None
  */
void vg_mqtt_session_close(void)
{
  if (g_fd >= 0)
    {
      vg_tcp_close(&g_fd);
    }

  g_online = false;
}

/**
  * @brief  发布 QoS0 retained status（含 network 与 uptime）。
  * @note   仅在 CONNACK 成功后调用；不做 TLS / AI topic。
  * @retval None
  */
static void publish_status(void)
{
  char payload[256];
  struct timespec mono;
  long long uptime_ms = 0;

  if (clock_gettime(CLOCK_MONOTONIC, &mono) == 0)
    {
      uptime_ms = (long long)mono.tv_sec * 1000LL +
                  mono.tv_nsec / 1000000LL;
    }

  snprintf(payload, sizeof(payload),
           "{\"device_id\":\"%s\",\"online\":true,"
           "\"firmware\":\"0.1.0\",\"build_mode\":\"TEST\","
           "\"network\":\"%s\",\"uptime_ms\":%lld,\"ts_ms\":0,"
           "\"time_quality\":\"unknown\"}",
           DEVID, g_net, uptime_ms);

  mqtt_publish(&g_client, "vg/" DEVID "/status", payload, strlen(payload),
               MQTT_PUBLISH_QOS_0 | MQTT_PUBLISH_RETAIN);
}

/**
  * @brief  在指定 backend 上建连、CONNECT，等待 CONNACK 后发 status。
  * @note   内部先 close 旧会话。status.network 使用 net_name（rj45|esp01|none）。
  *         约 2s（40×50ms）内未收到 CONNACK 则关闭并失败。
  *         vgmqtt 一次性调试命令语义不变。
  * @param  backend   VG_TCP_POSIX 或 VG_TCP_LESP。
  * @param  net_name  写入 status JSON 的 network 字段。
  * @retval 0   CONNACK 成功且已 publish status。
  * @retval -1  建连/CONNECT/CONNACK 失败（会话已关闭）。
  */
int vg_mqtt_session_open(vg_tcp_backend_t backend, const char *net_name)
{
  char port[8];
  uint8_t connflags;
  int ret;
  int i;

  /* Tear down any prior session before opening a new egress */

  vg_mqtt_session_close();
  strlcpy(g_net, net_name ? net_name : "none", sizeof(g_net));
  port_str(port, sizeof(port));

  g_fd = vg_tcp_open(backend, CONFIG_VG_MQTT_BROKER_HOST, port);
  if (g_fd < 0)
    {
      printf("vgnet: tcp connect %s:%s via %s failed\n",
             CONFIG_VG_MQTT_BROKER_HOST, port,
             vg_tcp_backend_str(backend));
      return -1;
    }

  /* Plaintext MQTT-C CONNECT with LWT on status topic */

  mqtt_init(&g_client, g_fd, g_tx, sizeof(g_tx), g_rx, sizeof(g_rx), NULL);
  connflags = MQTT_CONNECT_CLEAN_SESSION |
              MQTT_CONNECT_WILL_QOS_0 |
              MQTT_CONNECT_WILL_RETAIN;
  ret = mqtt_connect(&g_client, DEVID, "vg/" DEVID "/status",
                     VGMQTT_WILL_MSG, strlen(VGMQTT_WILL_MSG),
                     NULL, NULL, connflags, 15);
  if (ret != MQTT_OK)
    {
      vg_mqtt_session_close();
      return -1;
    }

  /* Wait for CONNACK; online flag stays false until event_connect */

  for (i = 0; i < 40 && !g_client.event_connect &&
       g_client.error == MQTT_OK; i++)
    {
      mqtt_sync(&g_client);
      usleep(50000);
    }

  if (!g_client.event_connect)
    {
      printf("vgnet: no CONNACK via %s\n", vg_tcp_backend_str(backend));
      vg_mqtt_session_close();
      return -1;
    }

  g_online = true;
  publish_status();
  mqtt_sync(&g_client);
  printf("vgnet: mqtt online network=%s backend=%s\n",
         g_net, vg_tcp_backend_str(backend));
  return 0;
}

/**
  * @brief  驱动 mqtt_sync；出错则关闭会话。
  * @note   由 net_mgr 周期调用；无在线会话时立即返回。
  * @retval None
  */
void vg_mqtt_session_poll(void)
{
  if (g_fd < 0 || !g_online)
    {
      return;
    }

  mqtt_sync(&g_client);
  if (g_client.error != MQTT_OK)
    {
      printf("vgnet: mqtt error %s\n", mqtt_error_str(g_client.error));
      vg_mqtt_session_close();
    }
}

/**
  * @brief  当前会话是否已收到 CONNACK。
  * @retval true   在线。
  * @retval false  未连接或已关闭。
  */
bool vg_mqtt_session_online(void)
{
  return g_online;
}

/****************************************************************************
 * app/velaguard/vgnet.c
 *
 * NSH 观察/注入命令，不启动 net_mgr。
 *
 * 用法：
 *   vgnet [status]
 *   vgnet inject <rj45|wifi> <down|up|auto>
 *   vgnet wifi <ssid> <psk>
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <string.h>

#include "vg_net_mgr.h"

/**
  * @brief  vgnet NSH 入口：查询状态或注入故障/改 Wi-Fi 凭据。
  * @note   本命令不是故障转移的启动条件；net_mgr 由 velaguard_app_main 拉起。
  *         inject 覆盖策略健康位，便于无拔线验收 AC；wifi 仅改 RAM 凭据。
  * @param  argc  参数个数。
  * @param  argv  参数向量；argv[1] 为子命令。
  * @retval 0  成功。
  * @retval 1  用法或参数错误。
  */
int main(int argc, FAR char *argv[])
{
  /* Default / explicit status: dump policy + bearer snapshot */

  if (argc < 2 || strcmp(argv[1], "status") == 0)
    {
      vg_net_mgr_print_status(stdout);
      return 0;
    }

  /* Force bearer health for lab acceptance without unplugging */

  if (strcmp(argv[1], "inject") == 0)
    {
      if (argc < 4)
        {
          fprintf(stderr, "Usage: vgnet inject <rj45|wifi> <down|up|auto>\n");
          return 1;
        }

      if (vg_net_mgr_inject(argv[2], argv[3]) != 0)
        {
          fprintf(stderr, "vgnet: bad inject\n");
          return 1;
        }

      printf("vgnet: inject %s %s\n", argv[2], argv[3]);
      return 0;
    }

  /* Override in-RAM AP credentials; join happens on next mgr retry */

  if (strcmp(argv[1], "wifi") == 0)
    {
      if (argc < 4)
        {
          fprintf(stderr, "Usage: vgnet wifi <ssid> <psk>\n");
          return 1;
        }

      if (vg_net_mgr_set_wifi(argv[2], argv[3]) != 0)
        {
          return 1;
        }

      printf("vgnet: wifi credentials updated (join on next retry)\n");
      return 0;
    }

  fprintf(stderr, "Usage: vgnet [status|inject ...|wifi ...]\n");
  return 1;
}

/****************************************************************************
 * app/velaguard/vg_net_policy.h
 *
 * Pure failover policy. No NuttX, POSIX, or ESP types.
 * Host tests compile this file with gcc.
 ****************************************************************************/

#ifndef __VELAGUARD_VG_NET_POLICY_H
#define __VELAGUARD_VG_NET_POLICY_H

#include <stdbool.h>
#include <stdint.h>

/** 连续 ping 失败达到该次数才判 RJ45 不健康。 */
#define VG_NET_PING_FAIL_N       3
/** 从 Wi-Fi 抢回 RJ45 前，RJ45 需持续健康的窗口（毫秒）。 */
#define VG_NET_RJ45_HOLD_MS      10000u
/** 退避基数：1s，每次指数 ×2。 */
#define VG_NET_BACKOFF_BASE_MS   1000u
/** 退避上限：60s。 */
#define VG_NET_BACKOFF_MAX_MS    60000u
/** Wi-Fi join 连续失败达到该次数时请求 ESP 软复位。 */
#define VG_NET_ESP_RESET_TRIES   5
/** RJ45 稳定在线达到该时长后重置退避指数。 */
#define VG_NET_STABLE_RESET_MS   (5u * 60u * 1000u)

/**
  * @brief  策略层对外状态机（供日志 / vgnet status）。
  * @note   VG_NET_DEGRADED 预留；当前实现主要用 DOWN / ONLINE_*。
  */
typedef enum
{
  VG_NET_DOWN = 0,
  VG_NET_CONNECTING,
  VG_NET_ONLINE_RJ45,
  VG_NET_ONLINE_WIFI,
  VG_NET_DEGRADED
} vg_net_state_t;

/**
  * @brief  活动业务出口（同时只应有一条）。
  */
typedef enum
{
  VG_EGRESS_NONE = 0,
  VG_EGRESS_RJ45,
  VG_EGRESS_WIFI
} vg_egress_t;

/**
  * @brief  TCP 传输后端，与 active_egress 一一对应。
  * @note   rj45 → posix（内核 eth0）；wifi → lesp（ESP AT 套接字）；none → 无 TCP。
  */
typedef enum
{
  VG_TCP_NONE = 0,
  VG_TCP_POSIX,
  VG_TCP_LESP
} vg_tcp_backend_t;

/**
  * @brief  测试注入：覆盖真实采样，便于无拔线验收。
  */
typedef enum
{
  VG_INJECT_AUTO = 0,
  VG_INJECT_FORCE_DOWN,
  VG_INJECT_FORCE_UP
} vg_inject_t;

/**
  * @brief  一拍采样输入（由 vg_net_mgr 填充后交给 step）。
  * @note   rj45_ping_sampled 为 false 时不得累加失败 streak，
  *         否则退避窗口内的空转会提前判挂。
  */
struct vg_net_sample
{
  bool rj45_link;
  bool rj45_has_ip;
  bool rj45_ping_ok;
  bool rj45_ping_sampled;
  bool wifi_assoc;
  bool wifi_has_ip;
};

/**
  * @brief  策略状态与输出标志。
  * @note   调用方每拍读：
  *         - active_egress / tcp_backend：该走哪条 TCP
  *         - tcp_reconnect：本拍是否发生出口切换（须关旧开新）
  *         - request_esp_reset：是否该软复位 ESP（由 note_wifi_join 置位）
  *         - next_rj45_probe_ms / next_wifi_join_ms：下次动作时间
  */
struct vg_net_policy
{
  vg_net_state_t     state;
  vg_egress_t        active_egress;
  vg_tcp_backend_t   tcp_backend;
  bool               tcp_reconnect;
  bool               request_esp_reset;
  vg_inject_t        inject_rj45;
  vg_inject_t        inject_wifi;
  int                jitter_pct;
  unsigned           rj45_ping_fail_streak;
  unsigned           wifi_fail_streak;
  unsigned           rj45_backoff_exp;
  unsigned           wifi_backoff_exp;
  uint64_t           rj45_healthy_since_ms;
  uint64_t           next_rj45_probe_ms;
  uint64_t           next_wifi_join_ms;
  uint64_t           online_since_ms;
  bool               prev_rj45_link;
  bool               initialized;
};

/**
  * @brief  清零并标记策略已初始化。
  * @param  p  策略对象。
  * @retval None
  */
void vg_net_policy_init(struct vg_net_policy *p);

/**
  * @brief  根据本拍采样推进故障转移策略。
  * @note   规则摘要：
  *         - RJ45 健康 = link ∧ DHCP ∧（连续 ping 失败 < 3）
  *         - RJ45 挂且 Wi-Fi 可用 → egress=wifi、backend=lesp
  *         - 从 wifi 抢回 rj45 需连续健康满 VG_NET_RJ45_HOLD_MS
  *         - 出口变化时 tcp_reconnect=true；调用方负责关旧 TCP 再开新
  *         - 仅在真实 ping 采样失败时调度退避；等待 tick 不得拉长探测周期
  * @param  p       策略对象（输入/输出）。
  * @param  now_ms  单调时钟毫秒。
  * @param  sample  本拍采样；不可为 NULL。
  * @retval None
  */
void vg_net_policy_step(struct vg_net_policy *p,
                        uint64_t now_ms,
                        const struct vg_net_sample *sample);

/**
  * @brief  记录一次 Wi-Fi join 结果，并在失败达阈值时请求软复位。
  * @param  p   策略对象。
  * @param  ok  true=join 成功；false=失败（累加 streak）。
  * @retval None
  */
void vg_net_policy_note_wifi_join(struct vg_net_policy *p, bool ok);

/**
  * @brief  计算指数退避毫秒数：base×2^exp，封顶 VG_NET_BACKOFF_MAX_MS。
  * @note   jitter_pct 预留；主机单测传 0。当前实现故意忽略 RNG。
  * @param  exp         退避指数（0 → 1s，1 → 2s，…）。
  * @param  jitter_pct  计划抖动百分比（未实现）。
  * @retval 退避等待毫秒数。
  */
uint32_t vg_net_policy_backoff_ms(unsigned exp, int jitter_pct);

/**
  * @brief  状态枚举转日志字符串。
  * @param  s  策略状态。
  * @retval 静态 C 字符串。
  */
const char *vg_net_state_str(vg_net_state_t s);

/**
  * @brief  出口枚举转日志字符串（rj45|wifi|none）。
  * @param  e  活动出口。
  * @retval 静态 C 字符串。
  */
const char *vg_egress_str(vg_egress_t e);

/**
  * @brief  TCP 后端枚举转日志字符串（posix|lesp|none）。
  * @param  b  传输后端。
  * @retval 静态 C 字符串。
  */
const char *vg_tcp_backend_str(vg_tcp_backend_t b);

#endif /* __VELAGUARD_VG_NET_POLICY_H */

